int main() {
    // Try to find and interact with the simulator's touch input device
    IOHIDManagerRef manager = IOHIDManagerCreate(kCFAllocatorDefault, kIOHIDOptionsTypeNone);
    IOHIDManagerSetDeviceMatching(manager, NULL);
    IOHIDManagerOpen(manager, kIOHIDOptionsTypeNone);

    CFArrayRef devices = IOHIDManagerCopyDevices(manager);
    if (devices) {
        CFIndex count = CFArrayGetCount(devices);
        NSLog(@"Found %ld HID devices", count);
        for (CFIndex i = 0; i < count; i++) {
            IOHIDDeviceRef device = (IOHIDDeviceRef)CFArrayGetValueAtIndex(devices, i);
            NSString *deviceName = (NSString *)IOHIDDeviceGetProperty(device, CFSTR(kIOHIDProductKey));
            NSLog(@"Device %ld: %@", i, deviceName);
        }
        CFRelease(devices);
    }

    IOHIDManagerClose(manager, kIOHIDOptionsTypeNone);
    CFRelease(manager);

    return 0;
}
