#import <Foundation/Foundation.h>
#import <UIKit/UIKit.h>

__attribute__((constructor))
void open_menu() {
    NSLog(@"Menu trigger library loaded!");

    // Try to find and trigger the menu
    dispatch_async(dispatch_get_main_queue(), ^{
        UIApplication *app = [UIApplication sharedApplication];
        UIWindow *window = [[app windows] firstObject];
        if (window) {
            UIViewController *rootVC = window.rootViewController;
            if (rootVC && [rootVC respondsToSelector:@selector(toggleMenu)]) {
                [rootVC performSelector:@selector(toggleMenu)];
            }
            // Try finding any buttons to tap
            for (UIView *subview in window.subviews) {
                if ([subview isKindOfClass:[UIButton class]]) {
                    UIButton *btn = (UIButton *)subview;
                    NSLog(@"Found button: %@", btn);
                    [btn sendActionsForControlEvents:UIControlEventTouchUpInside];
                    break;
                }
            }
        }
    });
}
EOF

